function parse_capcode($capcode, &$name = null)
{
  if ($name !== null && strpos($capcode, 'capcode_!') === 0) {
    $vip_name = parse_vip_capcode($capcode);

    if ($vip_name !== false) {
      $name = $vip_name;
      return 'verified';
    }

    return 'none';
  }

  return 'none';
}

